+    };
+
+    const App = () => `
+      <main class="app-shell">
+        ${ImagePreview({ image })}
+        ${DeleteDialog({ imageTitle: image.title })}
+      </main>
+    `;
+
+    const ImagePreview = ({ image }) => `
+      <section class="preview-card" aria-labelledby="page-title">
+        <header class="preview-header">
+          <div>
+            <p class="eyebrow">Image preview</p>
