+              </button>
+            </div>
+          </div>
+        </div>
+      </section>
+    `;
+
+    const DeleteDialog = ({ imageTitle }) => `
+      <div class="modal-root" id="delete-modal" hidden>
+        <div class="modal-backdrop" data-close-modal></div>
+        <section
+          class="modal-card"
+          id="delete-dialog"
