+            </p>
+          </div>
+          <div class="modal-actions">
+            <button class="button secondary" type="button" data-close-modal>Cancel</button>
+            <button class="button danger" type="button" data-confirm-delete>Delete permanently</button>
+          </div>
+        </section>
+      </div>
+    `;
+
+    document.getElementById("root").innerHTML = App();
+
+    const modal = document.getElementById("delete-modal");
+    const dialog = document.getElementById("delete-dialog");
+    const trigger = document.querySelector(".trigger");
+    const closeControls = document.querySelectorAll("[data-close-modal]");
+    const confirmButton = document.querySelector("[data-confirm-delete]");
+    let previousFocus = null;
+
+    const openModal = () => {
+      previousFocus = document.activeElement;
+      modal.hidden = false;
+      document.body.style.overflow = "hidden";
+      dialog.focus();
+    };
+
+    const closeModal = () => {
+      modal.hidden = true;
+      document.body.style.overflow = "";
+      previousFocus?.focus();
+    };
+
+    trigger.addEventListener("click", openModal);
+    closeControls.forEach((control) => control.addEventListener("click", closeModal));
+    confirmButton.addEventListener("click", closeModal);
+
+    document.addEventListener("keydown", (event) => {
+      if (event.key === "Escape" && !modal.hidden) {
+        closeModal();
+      }
+    });
+  </script>
+</body>
+</html>
+

